import json
items=[]
def add(prefix,typ,rows):
    for i,t in enumerate(rows,1):
        d={"id":"%s-%03d"%(prefix,i),"type":typ}
        d.update({"text":t} if isinstance(t,str) else t)
        items.append(d)
